for (var i = 0; i < 3; i++) {
  setTimeout(() => console.log("var:", i), 0);
}

for (let j = 0; j < 3; j++) {
  setTimeout(() => console.log("let:", j), 0);
}

// Output:
// var: 3
// var: 3
// var: 3
// let: 0
// let: 1
// let: 2

// Why?
