// Why?
// 1. Synchronous code runs first.
// 2. Promise callback runs as a microtask.
// 3. setTimeout callback runs as a task.

const user = {
  name: "Jeet",

  regular() {
    console.log(this.name);
  },

  arrow: () => {
    console.log(this.name);
  }
};

user.regular();
user.arrow();

// Output:
// Jeet
// undefined

// regular() gets this from the call: user.regular()
// arrow() does not create its own this.

